import{_ as e,c as i,o as r,a2 as l}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"プライバシーポリシー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy.md","filePath":"ja/guide/privacy.md","lastUpdated":1793163976000}'),t={name:"ja/guide/privacy.md"};function o(n,a,s,h,u,d){return r(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><p>NueZip は完全にオフライン優先のアプリケーションとして設計されています。お客様のプライバシーを最優先としています。</p><h2 id="ローカルのみの設計" tabindex="-1">ローカルのみの設計 <a class="header-anchor" href="#ローカルのみの設計" aria-label="Permalink to &quot;ローカルのみの設計&quot;">​</a></h2><ul><li>すべてのアーカイブ操作 — 圧縮、展開、変換、暗号化 — はお使いの Mac 上でのみ実行されます。</li><li>NueZip はお客様のファイルやデータを外部のサーバーにアップロードしません。</li><li>アプリを使用するためにアカウントや登録は不要です。</li><li>通常の操作にインターネット接続は必要ありません。</li></ul><h2 id="収集しないもの" tabindex="-1">収集しないもの <a class="header-anchor" href="#収集しないもの" aria-label="Permalink to &quot;収集しないもの&quot;">​</a></h2><ul><li>お客様のファイル、文書、アーカイブの内容は収集しません。</li><li>お客様のアクティビティ、閲覧行動、使用パターンを追跡しません。</li><li>ファイルのメタデータや個人情報を外部サーバーに送信しません。</li><li>サードパーティのアナリティクス、広告、トラッキング SDK を含みません。</li><li>テレメトリシステムは一切ありません。</li></ul><h2 id="ローカルに保存されるデータ" tabindex="-1">ローカルに保存されるデータ <a class="header-anchor" href="#ローカルに保存されるデータ" aria-label="Permalink to &quot;ローカルに保存されるデータ&quot;">​</a></h2><p>以下のデータはお客様のデバイス上にのみ保存されます：</p><ul><li><strong>アプリ設定</strong>: テーマ、言語の好み、圧縮の好み</li><li><strong>ライセンスキー</strong>: 購入した場合（ローカルのキーチェーンに安全に保存）</li><li><strong>最近使用したファイル一覧</strong>: クイックアクセス用の最近開いたアーカイブ</li><li><strong>パスワード記録</strong>: 保存することを選択した場合、ローカルのキーチェーンに保存</li><li><strong>ログ</strong>: トラブルシューティング用のデバッグログ（いつでも削除可能）</li></ul><h2 id="アプリが使用する権限" tabindex="-1">アプリが使用する権限 <a class="header-anchor" href="#アプリが使用する権限" aria-label="Permalink to &quot;アプリが使用する権限&quot;">​</a></h2><ul><li><strong>ファイルとフォルダ</strong>: アーカイブファイルの読み取りと内容の展開に必要です。</li><li><strong>Finder 機能拡張</strong>: オプション。Finder に右クリックのコンテキストメニュー項目を追加します。</li><li><strong>通知</strong>: オプション。長時間実行されるタスクの完了通知用です。</li></ul><p>これらの権限は <strong>システム設定 → プライバシーとセキュリティ</strong> でいつでも管理できます。</p><h2 id="アプリ内購入-ライセンス" tabindex="-1">アプリ内購入／ライセンス <a class="header-anchor" href="#アプリ内購入-ライセンス" aria-label="Permalink to &quot;アプリ内購入／ライセンス&quot;">​</a></h2><p>ライセンスの購入は Apple が Mac App Store を通じて処理します。NueZip はお客様の支払い情報を受け取ったり保存したりすることはありません。ライセンスのレシートは所有権の確認のためにローカルに保存されます。</p><h2 id="サードパーティサービス" tabindex="-1">サードパーティサービス <a class="header-anchor" href="#サードパーティサービス" aria-label="Permalink to &quot;サードパーティサービス&quot;">​</a></h2><p>NueZip はサードパーティのアナリティクス、広告、トラッキングサービスを一切含みません。アプリは完全に自己完結しています。</p><h2 id="プライバシーに関するリクエスト" tabindex="-1">プライバシーに関するリクエスト <a class="header-anchor" href="#プライバシーに関するリクエスト" aria-label="Permalink to &quot;プライバシーに関するリクエスト&quot;">​</a></h2><p>NueZip はすべてのデータをお客様のデバイス上にローカルに保存するため、当社のサーバー上に個人データを保持することはありません。プライバシーについてご質問がある場合は、お問い合わせください。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>プライバシーに関するご質問は、<a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> で issue を作成するか、メールでお問い合わせください。</p>',20)])])}const g=e(t,[["render",o]]);export{c as __pageData,g as default};
